{
  "vulnerable_symbols": [
    "axios.request"
  ],
  "trigger": "Node.js 中 Axios 通过带凭据代理发起请求并自动跟随重定向，且重定向目标不再经过该代理时，旧 Proxy-Authorization 头被发送到重定向目标。",
  "preconditions": [
    "运行在 Node.js 且使用 Axios 的 http adapter",
    "请求配置了带凭据的代理（如 HTTP_PROXY/HTTPS_PROXY 或 proxy 含 user:pass）",
    "自动重定向启用（maxRedirects 不为 0）",
    "重定向目标不再经过该代理（如 https 目标且 HTTPS_PROXY 未设置或 NO_PROXY 命中）"
  ],
  "exploit_evidence": [
    {
      "src": 2,
      "kind": "poc",
      "quote": "Includes proof of concept details, patch analysis for both v1.x and v0.x lines, and practical detection strategies."
    }
  ],
  "fixed_version": "1.16.0",
  "summary_zh": "Axios 1.7.4 在 Node.js 经认证代理请求并自动重定向到非代理目标时，可能泄露代理凭据，升级 1.16.0。"
}
